$(() => {
  $(document).on("click","#cmptbk_agecheck",function(){
    const inputsGrp = $('#c-agevaldchck').find('input');
    if($(this).is(":checked")){
      $(this).val(1);
      $("#ic-agecheck").html(`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="18" height="18" viewBox="0 0 18 18" fill="none"><rect width="18" height="18" fill="url(#pattern0)"/><defs><pattern id="pattern0" patternContentUnits="objectBoundingBox" width="1" height="1"><use xlink:href="#image0" transform="scale(0.0555556)"/></pattern><image id="image0" width="18" height="18" xlink:href="data:image/png;base64,"/></defs></svg>`);
      $("#c-agevaldchck").removeClass("d-none");
      $.each(inputsGrp, function(i, e){
        $(this).attr('required', 'required');
      });
    }else{
      $(this).val(0);
      $("#ic-agecheck").html(`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="18" height="18" viewBox="0 0 18 18"><defs><clipPath id="clip-Web_1920_1"><rect width="18" height="18"/></clipPath></defs><g id="Web_1920_1" data-name="Web 1920 – 1" clip-path="url(#clip-Web_1920_1)"><rect width="18" height="18" fill="#fff"/><g id="Rectángulo_1" data-name="Rectángulo 1" fill="none" stroke="#696158" stroke-width="1.8"><rect width="18" height="18" stroke="none"/><rect x="0.9" y="0.9" width="16.2" height="16.2" fill="none"/></g></g></svg>`);
      $("#c-agevaldchck").addClass("d-none");
      $.each(inputsGrp, function(i, e){
        $(this).removeAttr('required');
      });
    }
  });
  var locationsGET = window.location.href;
  var csrfTokenFrm = $("#csl-fGv8n09c__sGaYs45").find("input[name='_token']").val();
  // ------------------- LISTAR DEPARTAMENTOS - LIBRO DE RECLAMACIONES
  getAllDepartamentos();
  var tmpListDepartamentos = ``;
  function getAllDepartamentos(){
    // e.preventDefault();
    $.ajax({
      headers: {
        'X-CSRF-TOKEN': csrfTokenFrm
      },
      url: locationsGET+"/departamento",
      type: "POST",
      dataType: "JSON",
      success: function(e){
        if(e.length != "undefined" || e != ""){
          var r = e.data;
          var tmpFor = ``;
          $.each(r, function(i,e){
            tmpFor += `<option value="${e.id}" data-code="${e.departamento_code}">${e.departamento_name}</option>`;
          });
          // let start = `<option value="">Elige Departamento</option>`;
          // tmpListDepartamentos = start + tmpFor;
          tmpListDepartamentos = tmpFor;
          $("#cmptbk_departamento_id").append(tmpListDepartamentos);
        }else{
          console.log("Lo sentimos, hubo un error al obtener la información");
        }
      }
    });
  }
  // ------------------- SELECCIONAR DEPARTAMENTO - LIBRO DE RECLAMACIONES
  $(document).on("change","#cmptbk_departamento_id",function(){
    let departamento_id = $(this).val();
    let departamento_code = $('option:selected', this).attr('data-code');
    let url = $(this).attr('data-href');
    getProvinciaByIdDepartamento(url,departamento_code);
  });
  // ------------------- LISTAR PROVINCIAS POR DEPARTAMENTOS - LIBRO DE RECLAMACIONES
  function getProvinciaByIdDepartamento(url,departamento_code){
    $.get(url+'?departamento_code='+departamento_code,function(data){
      if(data.length != "undefined"){
        if(data.data.length != 0 && data.data.length != "[]"){
          let response = data.data;
          let view_html = ``;
          $.each(response , function(i, e){
            view_html += `<option value="${e.id}" data-code="${e.provincia_code}">${e.provincia_name}</option>`;
          });
          let start = `<option value="">Seleccione una opción</option>`;
          $('#cmptbk_provincia_id').html(start+view_html);
        }else{
          let view_html = `<option value="">No hay información</option>`;
          $('#cmptbk_provincia_id').html(view_html);
        }
      }else{
        let view_html = `<option value="">No hay información</option>`;
        $('#cmptbk_provincia_id').html(view_html);
      }
    });
  }
  // ------------------- SELECCIONAR PROVINCIA - LIBRO DE RECLAMACIONES
  $(document).on("change","#cmptbk_provincia_id",function(){
    let provincia_id = $(this).val();
    let provincia_code = $('option:selected', this).attr('data-code');
    let url = $(this).attr('data-href');
    getDistritoByIdCiudad(url,provincia_code);
  });
  // ------------------- LISTAR DISTRITOS POR PROVINCIA - LIBRO DE RECLAMACIONES
  function getDistritoByIdCiudad(url,provincia_code){
    $.get(url+'?provincia_code='+provincia_code,function(data){
      if(data.length != "undefined"){
        if(data.data.length != 0 && data.data.length != "[]"){
          let response = data.data;
          let view_html = ``;
          $.each(response , function(i, e){
            view_html += `<option value="${e.id}" data-code="${e.distrito_code}">${e.distrito_name}</option>`;
          });
          let start = `<option value="">Seleccione una opción</option>`;
          $('#cmptbk_distrito_id').html(start+view_html);
        }else{
          let view_html = `<option value="">No hay información</option>`;
          $('#cmptbk_distrito_id').html(view_html);
        }
      }else{
        let view_html = `<option value="">No hay información</option>`;
        $('#cmptbk_distrito_id').html(view_html);
      }
    });
  }
  // ------------------- LIMITADOR DE CARACTERES PARA TEXTAREAS - LIBRO DE RECLAMACIONES
  var maxLength = 350;
  $('.ipt-mssgtxt_cmptbk').on('input', function(){
    var textLength = $(this).val().length;
    if(textLength > maxLength){
      $(this).val($(this).val().substring(0, maxLength));
      textLength = maxLength;
    }
    $(this).parent().find('#charCount').text(textLength);
  });

  $('.ipt-mssgtxt_cmptbk').on('keypress keyup', function(event){
    var textLength = $(this).val().length;
    if(textLength >= maxLength && event.which !== 8 && event.which !== 46){
      event.preventDefault();
      $(this).parent().find('#charCount').addClass('limit-max');
    }else{
      $(this).parent().find('#charCount').removeClass('limit-max');
    }
  });
  // ------------------- FORMATEO DE PRECIOS - LIBRO DE RECLAMACIONES
  $(document).on("keyup", "input[data-valformat=withcomedecimal]", function(e){
    let val = e.target.value;
    let val_formatNumber = val.toString().replace(/[^\d.]/g, "").replace(/^(\d*\.)(.*)\.(.*)$/, '$1$2$3').replace(/\.(\d{2})\d+/, '.$1').replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    $(this).val(val_formatNumber);
  });
});